import {
  Document,
  Paragraph,
  TextRun,
  HeadingLevel,
  AlignmentType,
  Table,
  TableRow,
  TableCell,
  WidthType,
  BorderStyle,
  Packer,
} from 'docx';
import { marked, Tokens } from 'marked';
import type { TypographyTemplate } from './templates';

function mmToTwip(mm: number): number {
  return Math.round((mm / 25.4) * 1440);
}

function ptToHalfPt(pt: number): number {
  return Math.round(pt * 2);
}

interface RunOptions {
  font: string;
  size: number;
  color: string;
  bold?: boolean;
  italics?: boolean;
  strike?: boolean;
  style?: string;
}

/** 递归解析内联 token，生成带格式的 TextRun 数组 */
function extractTextRuns(
  tokens: any[] | undefined,
  opts: RunOptions
): TextRun[] {
  if (!tokens) return [];
  const runs: TextRun[] = [];

  for (const t of tokens) {
    switch (t.type) {
      case 'text': {
        if (t.tokens && Array.isArray(t.tokens)) {
          runs.push(...extractTextRuns(t.tokens, opts));
        } else {
          runs.push(new TextRun({ text: t.text || '', ...opts }));
        }
        break;
      }
      case 'strong':
        runs.push(...extractTextRuns(t.tokens, { ...opts, bold: true }));
        break;
      case 'em':
        runs.push(...extractTextRuns(t.tokens, { ...opts, italics: true }));
        break;
      case 'del':
        runs.push(...extractTextRuns(t.tokens, { ...opts, strike: true }));
        break;
      case 'codespan':
        runs.push(
          new TextRun({
            text: t.text || '',
            font: 'Consolas',
            size: opts.size,
            color: opts.color,
          })
        );
        break;
      case 'link':
        runs.push(...extractTextRuns(t.tokens, { ...opts, style: 'Hyperlink' }));
        break;
      case 'br':
        runs.push(new TextRun({ break: 1 }));
        break;
      case 'escape':
        runs.push(new TextRun({ text: t.text || '', ...opts }));
        break;
      default:
        if ('tokens' in t && Array.isArray(t.tokens)) {
          runs.push(...extractTextRuns(t.tokens, opts));
        } else if ('text' in t) {
          runs.push(new TextRun({ text: t.text || '', ...opts }));
        }
        break;
    }
  }

  return runs;
}

/** 提取纯文本（用于表格等不需要保留格式的场景） */
function extractPlainText(tokens: any[] | undefined): string {
  if (!tokens) return '';
  return tokens
    .map((t) => {
      if (t.type === 'text') return t.text || '';
      if (t.type === 'strong' || t.type === 'em' || t.type === 'del')
        return extractPlainText(t.tokens);
      if (t.type === 'codespan') return t.text || '';
      if ('tokens' in t && Array.isArray(t.tokens))
        return extractPlainText(t.tokens);
      if ('text' in t) return t.text || '';
      return '';
    })
    .join('');
}

interface ParsedBlock {
  type: 'heading' | 'paragraph' | 'list' | 'blockquote' | 'table' | 'hr' | 'code';
  level?: number;
  tokens?: any[];
  items?: any[][];
  rows?: string[][];
  lang?: string;
  text?: string;
  ordered?: boolean;
}

function parseMarkdown(md: string): ParsedBlock[] {
  const tokens = marked.lexer(md);
  const blocks: ParsedBlock[] = [];

  for (const token of tokens) {
    switch (token.type) {
      case 'heading':
        blocks.push({
          type: 'heading',
          level: token.depth,
          tokens: token.tokens,
        });
        break;
      case 'paragraph':
        blocks.push({
          type: 'paragraph',
          tokens: token.tokens,
        });
        break;
      case 'list': {
        const listToken = token as Tokens.List;
        blocks.push({
          type: 'list',
          ordered: listToken.ordered,
          items: listToken.items.map((item) => item.tokens || []),
        });
        break;
      }
      case 'blockquote':
        blocks.push({
          type: 'blockquote',
          tokens: (token as Tokens.Blockquote).tokens,
        });
        break;
      case 'table': {
        const tableToken = token as Tokens.Table;
        const headerRow = tableToken.header.map((cell) =>
          extractPlainText(cell.tokens)
        );
        const dataRows = tableToken.rows.map((row) =>
          row.map((cell) => extractPlainText(cell.tokens))
        );
        blocks.push({
          type: 'table',
          rows: [headerRow, ...dataRows],
        });
        break;
      }
      case 'hr':
        blocks.push({ type: 'hr' });
        break;
      case 'code':
        blocks.push({
          type: 'code',
          lang: (token as Tokens.Code).lang,
          text: (token as Tokens.Code).text,
        });
        break;
    }
  }
  return blocks;
}

function getLineSpacing(template: TypographyTemplate) {
  const lh = template.spacing.lineHeight;
  if (lh > 10) {
    // 固定磅值：转换为 twip (1pt = 20 twip)
    return { line: Math.round(lh * 20), lineRule: 'exact' as const };
  }
  // 倍数：docx 用 240 = 单倍行距
  return { line: Math.round(lh * 240), lineRule: 'auto' as const };
}

export async function exportToDocx(
  markdown: string,
  template: TypographyTemplate
): Promise<void> {
  const blocks = parseMarkdown(markdown);
  const children: (Paragraph | Table)[] = [];

  const headingFont = template.fonts.heading;
  const bodyFont = template.fonts.body;
  const headingColor = template.colors.heading;
  const bodyColor = template.colors.body;
  const lineSpacing = getLineSpacing(template);

  const bodyRunOpts: RunOptions = {
    font: bodyFont,
    size: ptToHalfPt(template.sizes.body),
    color: bodyColor,
  };

  for (const block of blocks) {
    switch (block.type) {
      case 'heading': {
        const sizes = template.sizes;
        let fontSize: number;
        let headingLevel: (typeof HeadingLevel)[keyof typeof HeadingLevel];

        switch (block.level) {
          case 1:
            fontSize = sizes.h1;
            headingLevel = HeadingLevel.HEADING_1;
            break;
          case 2:
            fontSize = sizes.h2;
            headingLevel = HeadingLevel.HEADING_2;
            break;
          default:
            fontSize = sizes.h3;
            headingLevel = HeadingLevel.HEADING_3;
        }

        const headingRunOpts: RunOptions = {
          font: headingFont,
          size: ptToHalfPt(fontSize),
          color: headingColor,
          bold: true,
        };

        children.push(
          new Paragraph({
            heading: headingLevel,
            alignment:
              block.level === 1 ? AlignmentType.CENTER : AlignmentType.LEFT,
            spacing: {
              before: template.spacing.paragraphSpacing * 20,
              after: template.spacing.paragraphSpacing * 10,
              ...lineSpacing,
            },
            children: extractTextRuns(block.tokens, headingRunOpts),
          })
        );
        break;
      }
      case 'paragraph': {
        const indent =
          template.spacing.firstLineIndent > 0
            ? { firstLine: template.spacing.firstLineIndent * 20 }
            : undefined;

        children.push(
          new Paragraph({
            spacing: lineSpacing,
            indent,
            children: extractTextRuns(block.tokens, bodyRunOpts),
          })
        );
        break;
      }
      case 'list': {
        const items = block.items || [];
        for (let i = 0; i < items.length; i++) {
          const prefix = block.ordered ? `${i + 1}. ` : '\u2022 ';
          const indent =
            template.spacing.firstLineIndent > 0
              ? { left: template.spacing.firstLineIndent * 20 }
              : { left: 480 };

          // 前缀作为单独的 TextRun，内容用 extractTextRuns 保留格式
          const contentRuns = extractTextRuns(items[i], bodyRunOpts);
          const runs = [
            new TextRun({ text: prefix, ...bodyRunOpts }),
            ...contentRuns,
          ];

          children.push(
            new Paragraph({
              spacing: lineSpacing,
              indent,
              children: runs,
            })
          );
        }
        break;
      }
      case 'blockquote': {
        const quoteRunOpts: RunOptions = {
          font: bodyFont,
          size: ptToHalfPt(template.sizes.body),
          color: '666666',
          italics: true,
        };

        children.push(
          new Paragraph({
            spacing: { before: 120, after: 120, ...lineSpacing },
            indent: { left: 480 },
            border: {
              left: {
                style: BorderStyle.SINGLE,
                size: 6,
                color: '999999',
                space: 10,
              },
            },
            children: extractTextRuns(block.tokens, quoteRunOpts),
          })
        );
        break;
      }
      case 'table': {
        const rows = block.rows || [];
        if (rows.length === 0) break;

        const colCount = rows[0].length;
        const tableRows: TableRow[] = rows.map((row, rowIdx) => {
          const cells = row.map(
            (cell) =>
              new TableCell({
                width: {
                  size: Math.floor(9000 / colCount),
                  type: WidthType.DXA,
                },
                borders: {
                  top: { style: BorderStyle.SINGLE, size: 1, color: '999999' },
                  bottom: { style: BorderStyle.SINGLE, size: 1, color: '999999' },
                  left: { style: BorderStyle.SINGLE, size: 1, color: '999999' },
                  right: { style: BorderStyle.SINGLE, size: 1, color: '999999' },
                },
                shading: rowIdx === 0 ? { fill: 'F0F0F0' } : undefined,
                children: [
                  new Paragraph({
                    alignment: AlignmentType.CENTER,
                    children: [
                      new TextRun({
                        text: cell,
                        font: bodyFont,
                        size: ptToHalfPt(template.sizes.body - 1),
                        bold: rowIdx === 0,
                        color: bodyColor,
                      }),
                    ],
                  }),
                ],
              })
          );
          return new TableRow({ children: cells });
        });

        children.push(
          new Table({
            rows: tableRows,
            width: { size: 9000, type: WidthType.DXA },
          })
        );
        break;
      }
      case 'hr': {
        children.push(
          new Paragraph({
            spacing: { before: 200, after: 200 },
            border: {
              bottom: { style: BorderStyle.SINGLE, size: 1, color: 'CCCCCC' },
            },
            children: [],
          })
        );
        break;
      }
      case 'code': {
        children.push(
          new Paragraph({
            spacing: { before: 120, after: 120 },
            shading: { fill: 'F5F5F5' },
            border: {
              left: { style: BorderStyle.SINGLE, size: 1, color: 'DDDDDD', space: 8 },
              right: { style: BorderStyle.SINGLE, size: 1, color: 'DDDDDD', space: 8 },
              top: { style: BorderStyle.SINGLE, size: 1, color: 'DDDDDD', space: 8 },
              bottom: { style: BorderStyle.SINGLE, size: 1, color: 'DDDDDD', space: 8 },
            },
            children: [
              new TextRun({
                text: block.text || '',
                font: 'Consolas',
                size: ptToHalfPt(template.sizes.body - 1),
                color: '333333',
              }),
            ],
          })
        );
        break;
      }
    }
  }

  const doc = new Document({
    sections: [
      {
        properties: {
          page: {
            margin: {
              top: mmToTwip(template.margins.top),
              right: mmToTwip(template.margins.right),
              bottom: mmToTwip(template.margins.bottom),
              left: mmToTwip(template.margins.left),
            },
          },
        },
        children,
      },
    ],
  });

  const blob = await Packer.toBlob(doc);
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = '墨印导出文档.docx';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
