import { useEditorStore } from '@/hooks/useEditorStore';
import type { TypographyTemplate } from '@/lib/templates';

interface SettingsPanelProps {
  template: TypographyTemplate;
  onUpdate: (partial: Partial<TypographyTemplate>) => void;
}

export default function SettingsPanel({ template, onUpdate }: SettingsPanelProps) {
  const { showSettings, toggleSettings } = useEditorStore();

  if (!showSettings) return null;

  const updateFonts = (key: 'heading' | 'body', value: string) => {
    onUpdate({ fonts: { ...template.fonts, [key]: value } });
  };

  const updateSizes = (key: string, value: number) => {
    onUpdate({ sizes: { ...template.sizes, [key]: value } });
  };

  const updateSpacing = (key: string, value: number) => {
    onUpdate({ spacing: { ...template.spacing, [key]: value } });
  };

  const updateMargins = (key: string, value: number) => {
    onUpdate({ margins: { ...template.margins, [key]: value } });
  };

  const fontOptions = ['宋体', '黑体', '仿宋', '楷体', '微软雅黑', '方正小标宋简体'];

  return (
    <div className="fixed right-0 top-0 h-full w-80 bg-ink-50 border-l border-ink-200 shadow-2xl z-50 overflow-y-auto">
      <div className="p-5">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-lg font-song font-bold text-ink-900">排版参数</h2>
          <button
            onClick={toggleSettings}
            className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-ink-200 text-ink-600 transition-colors"
          >
            ✕
          </button>
        </div>

        {/* 字体设置 */}
        <section className="mb-6">
          <h3 className="text-sm font-hei font-semibold text-ink-800 mb-3 flex items-center gap-2">
            <span className="w-1 h-4 bg-vermilion-500 rounded-full" />
            字体
          </h3>
          <div className="space-y-3">
            <label className="block">
              <span className="text-xs text-ink-600">标题字体</span>
              <select
                value={template.fonts.heading}
                onChange={(e) => updateFonts('heading', e.target.value)}
                className="mt-1 w-full px-3 py-1.5 text-sm border border-ink-200 rounded bg-white focus:border-vermilion-400 focus:outline-none"
              >
                {fontOptions.map((f) => (
                  <option key={f} value={f}>{f}</option>
                ))}
              </select>
            </label>
            <label className="block">
              <span className="text-xs text-ink-600">正文字体</span>
              <select
                value={template.fonts.body}
                onChange={(e) => updateFonts('body', e.target.value)}
                className="mt-1 w-full px-3 py-1.5 text-sm border border-ink-200 rounded bg-white focus:border-vermilion-400 focus:outline-none"
              >
                {fontOptions.map((f) => (
                  <option key={f} value={f}>{f}</option>
                ))}
              </select>
            </label>
          </div>
        </section>

        {/* 字号设置 */}
        <section className="mb-6">
          <h3 className="text-sm font-hei font-semibold text-ink-800 mb-3 flex items-center gap-2">
            <span className="w-1 h-4 bg-gold-500 rounded-full" />
            字号
          </h3>
          <div className="space-y-3">
            {[
              { key: 'h1', label: '一级标题', min: 12, max: 36 },
              { key: 'h2', label: '二级标题', min: 10, max: 28 },
              { key: 'h3', label: '三级标题', min: 10, max: 24 },
              { key: 'body', label: '正文', min: 8, max: 20 },
            ].map(({ key, label, min, max }) => (
              <label key={key} className="block">
                <div className="flex justify-between text-xs text-ink-600">
                  <span>{label}</span>
                  <span>{template.sizes[key as keyof typeof template.sizes]}pt</span>
                </div>
                <input
                  type="range"
                  min={min}
                  max={max}
                  value={template.sizes[key as keyof typeof template.sizes]}
                  onChange={(e) => updateSizes(key, Number(e.target.value))}
                  className="mt-1 w-full accent-vermilion-500"
                />
              </label>
            ))}
          </div>
        </section>

        {/* 间距设置 */}
        <section className="mb-6">
          <h3 className="text-sm font-hei font-semibold text-ink-800 mb-3 flex items-center gap-2">
            <span className="w-1 h-4 bg-ink-500 rounded-full" />
            间距
          </h3>
          <div className="space-y-3">
            <label className="block">
              <div className="flex justify-between text-xs text-ink-600">
                <span>行距</span>
                <span>
                  {template.spacing.lineHeight > 10
                    ? `${template.spacing.lineHeight}磅固定`
                    : `${template.spacing.lineHeight}倍`}
                </span>
              </div>
              <input
                type="range"
                min={1}
                max={40}
                step={0.5}
                value={template.spacing.lineHeight}
                onChange={(e) => updateSpacing('lineHeight', Number(e.target.value))}
                className="mt-1 w-full accent-vermilion-500"
              />
            </label>
            <label className="block">
              <div className="flex justify-between text-xs text-ink-600">
                <span>段间距</span>
                <span>{template.spacing.paragraphSpacing}pt</span>
              </div>
              <input
                type="range"
                min={0}
                max={24}
                value={template.spacing.paragraphSpacing}
                onChange={(e) => updateSpacing('paragraphSpacing', Number(e.target.value))}
                className="mt-1 w-full accent-vermilion-500"
              />
            </label>
            <label className="block">
              <div className="flex justify-between text-xs text-ink-600">
                <span>首行缩进</span>
                <span>{template.spacing.firstLineIndent}pt</span>
              </div>
              <input
                type="range"
                min={0}
                max={48}
                step={2}
                value={template.spacing.firstLineIndent}
                onChange={(e) => updateSpacing('firstLineIndent', Number(e.target.value))}
                className="mt-1 w-full accent-vermilion-500"
              />
            </label>
          </div>
        </section>

        {/* 页边距设置 */}
        <section className="mb-6">
          <h3 className="text-sm font-hei font-semibold text-ink-800 mb-3 flex items-center gap-2">
            <span className="w-1 h-4 bg-xuan-500 rounded-full" />
            页边距
          </h3>
          <div className="space-y-3">
            {[
              { key: 'top', label: '上' },
              { key: 'bottom', label: '下' },
              { key: 'left', label: '左' },
              { key: 'right', label: '右' },
            ].map(({ key, label }) => (
              <label key={key} className="block">
                <div className="flex justify-between text-xs text-ink-600">
                  <span>{label}边距</span>
                  <span>{template.margins[key as keyof typeof template.margins]}mm</span>
                </div>
                <input
                  type="range"
                  min={10}
                  max={50}
                  value={template.margins[key as keyof typeof template.margins]}
                  onChange={(e) => updateMargins(key, Number(e.target.value))}
                  className="mt-1 w-full accent-vermilion-500"
                />
              </label>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
}
