import { marked } from 'marked';
import type { TypographyTemplate } from '@/lib/templates';

interface PreviewProps {
  markdown: string;
  template: TypographyTemplate;
}

export default function Preview({ markdown, template }: PreviewProps) {
  const html = markdown ? marked.parse(markdown, { async: false }) as string : '';

  const headingFont = template.fonts.heading;
  const bodyFont = template.fonts.body;

  // 区分行距模式：>10 为固定磅值，≤10 为倍数
  const lh = template.spacing.lineHeight;
  const lineHeightValue = lh > 10 ? `${lh}pt` : String(lh);

  const styleObj: React.CSSProperties = {
    '--tpl-h1-size': `${template.sizes.h1}pt`,
    '--tpl-h2-size': `${template.sizes.h2}pt`,
    '--tpl-h3-size': `${template.sizes.h3}pt`,
    '--tpl-body-size': `${template.sizes.body}pt`,
    '--tpl-heading-font': headingFont,
    '--tpl-body-font': bodyFont,
    '--tpl-heading-color': template.colors.heading,
    '--tpl-body-color': template.colors.body,
    '--tpl-line-height': lineHeightValue,
    '--tpl-first-indent': `${template.spacing.firstLineIndent}pt`,
    '--tpl-para-spacing': `${template.spacing.paragraphSpacing}pt`,
  } as React.CSSProperties;

  return (
    <div
      className="preview-container w-full h-full overflow-auto"
      style={styleObj}
    >
      {markdown ? (
        <div
          className="preview-paper"
          dangerouslySetInnerHTML={{ __html: html }}
        />
      ) : (
        <div className="flex items-center justify-center h-full text-xuan-400 font-song">
          <div className="text-center">
            <div className="text-5xl mb-4 opacity-30">墨</div>
            <div className="text-sm">在左侧输入 Markdown 内容</div>
            <div className="text-xs mt-1 opacity-60">排版预览将在此处实时显示</div>
          </div>
        </div>
      )}
    </div>
  );
}
