import { create } from 'zustand';
import { TypographyTemplate, templates } from '@/lib/templates';

interface EditorState {
  markdown: string;
  currentTemplate: TypographyTemplate;
  showSettings: boolean;
  setMarkdown: (md: string) => void;
  setTemplate: (tpl: TypographyTemplate) => void;
  updateTemplate: (partial: Partial<TypographyTemplate>) => void;
  toggleSettings: () => void;
}

export const useEditorStore = create<EditorState>((set) => ({
  markdown: '',
  currentTemplate: templates[0],
  showSettings: false,
  setMarkdown: (md) => set({ markdown: md }),
  setTemplate: (tpl) => set({ currentTemplate: tpl }),
  updateTemplate: (partial) =>
    set((state) => ({
      currentTemplate: { ...state.currentTemplate, ...partial },
    })),
  toggleSettings: () => set((state) => ({ showSettings: !state.showSettings })),
}));
