import { useCallback, useRef, useState } from 'react';
import { Download, Settings, FileText, BookOpen, Pen, Sparkles, ChevronDown } from 'lucide-react';
import { useEditorStore } from '@/hooks/useEditorStore';
import { templates, sampleDocuments } from '@/lib/templates';
import { exportToDocx } from '@/lib/exportDocx';
import Preview from '@/components/Preview';
import SettingsPanel from '@/components/SettingsPanel';

export default function Home() {
  const {
    markdown,
    currentTemplate,
    showSettings,
    setMarkdown,
    setTemplate,
    updateTemplate,
    toggleSettings,
  } = useEditorStore();

  const [exporting, setExporting] = useState(false);
  const [exportStatus, setExportStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [activeTab, setActiveTab] = useState<'editor' | 'preview'>('editor');
  const [showSampleMenu, setShowSampleMenu] = useState(false);
  const sampleMenuRef = useRef<HTMLDivElement>(null);

  const handleExport = useCallback(async () => {
    if (!markdown.trim()) return;
    setExporting(true);
    setExportStatus('idle');
    try {
      await exportToDocx(markdown, currentTemplate);
      setExportStatus('success');
      setTimeout(() => setExportStatus('idle'), 3000);
    } catch (err) {
      console.error('导出失败:', err);
      setExportStatus('error');
      setTimeout(() => setExportStatus('idle'), 3000);
    } finally {
      setExporting(false);
    }
  }, [markdown, currentTemplate]);

  const handleLoadSample = useCallback(
    (sampleId: string) => {
      const sample = sampleDocuments.find((s) => s.id === sampleId);
      if (sample) {
        setMarkdown(sample.markdown);
        // 自动切换到推荐模板
        const tpl = templates.find((t) => t.id === sample.recommendedTemplate);
        if (tpl) setTemplate(tpl);
      }
      setShowSampleMenu(false);
    },
    [setMarkdown, setTemplate]
  );

  const handleTemplateChange = useCallback(
    (tplId: string) => {
      const tpl = templates.find((t) => t.id === tplId);
      if (tpl) setTemplate(tpl);
    },
    [setTemplate]
  );

  return (
    <div className="h-screen flex flex-col bg-ink-950 text-ink-100 overflow-hidden">
      {/* 顶部导航 */}
      <header className="flex items-center justify-between px-5 py-3 bg-ink-950 border-b border-ink-800/60 shrink-0">
        {/* Logo */}
        <div className="flex items-center gap-3">
          <div className="relative w-9 h-9 flex items-center justify-center">
            <div className="absolute inset-0 bg-vermilion-500 rounded-sm rotate-3 shadow-lg shadow-vermilion-500/20" />
            <span className="relative font-song font-black text-ink-50 text-base leading-none mt-0.5">墨</span>
          </div>
          <div>
            <h1 className="font-song font-bold text-lg text-ink-50 tracking-wider leading-tight">墨印</h1>
            <p className="text-[10px] text-ink-400 font-hei tracking-widest">MOYIN · 智能排版引擎</p>
          </div>
        </div>

        {/* 模板选择 */}
        <div className="flex items-center gap-2">
          <div className="flex bg-ink-900 rounded-lg p-1 border border-ink-800/50">
            {templates.map((tpl) => (
              <button
                key={tpl.id}
                onClick={() => handleTemplateChange(tpl.id)}
                className={`px-3 py-1.5 text-xs font-hei rounded-md transition-all duration-200 ${
                  currentTemplate.id === tpl.id
                    ? 'bg-vermilion-500 text-white shadow-md shadow-vermilion-500/30'
                    : 'text-ink-300 hover:text-ink-100 hover:bg-ink-800'
                }`}
              >
                {tpl.name}
              </button>
            ))}
          </div>
        </div>

        {/* 操作按钮 */}
        <div className="flex items-center gap-2">
          <div className="relative" ref={sampleMenuRef}>
            <button
              onClick={() => setShowSampleMenu(!showSampleMenu)}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-hei bg-ink-800 hover:bg-ink-700 text-ink-200 rounded-lg transition-colors border border-ink-700/50"
            >
              <FileText size={14} />
              示例
              <ChevronDown size={12} className={`transition-transform ${showSampleMenu ? 'rotate-180' : ''}`} />
            </button>
            {showSampleMenu && (
              <div className="absolute top-full mt-1 left-0 w-56 bg-ink-900 border border-ink-700/50 rounded-lg shadow-xl shadow-black/30 overflow-hidden z-50">
                {sampleDocuments.map((sample) => (
                  <button
                    key={sample.id}
                    onClick={() => handleLoadSample(sample.id)}
                    className="w-full px-4 py-2.5 text-left hover:bg-ink-800 transition-colors border-b border-ink-800/50 last:border-0"
                  >
                    <div className="text-xs font-hei text-ink-100">{sample.title}</div>
                    <div className="text-[10px] text-ink-500 mt-0.5">{sample.description}</div>
                  </button>
                ))}
              </div>
            )}
          </div>
          <button
            onClick={toggleSettings}
            className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-hei rounded-lg transition-colors border ${
              showSettings
                ? 'bg-gold-500/20 text-gold-300 border-gold-500/40'
                : 'bg-ink-800 hover:bg-ink-700 text-ink-200 border-ink-700/50'
            }`}
          >
            <Settings size={14} />
            参数
          </button>
          <button
            onClick={handleExport}
            disabled={!markdown.trim() || exporting}
            className={`flex items-center gap-1.5 px-4 py-1.5 text-xs font-hei rounded-lg transition-all shadow-lg disabled:shadow-none ${
              exportStatus === 'success'
                ? 'bg-green-600 text-white shadow-green-600/20'
                : exportStatus === 'error'
                ? 'bg-red-600 text-white shadow-red-600/20'
                : 'bg-vermilion-500 hover:bg-vermilion-600 disabled:bg-ink-800 disabled:text-ink-500 text-white shadow-vermilion-500/20'
            }`}
          >
            <Download size={14} />
            {exporting ? '导出中...' : exportStatus === 'success' ? '已导出 ✓' : exportStatus === 'error' ? '导出失败' : '导出 docx'}
          </button>
        </div>
      </header>

      {/* 主体：编辑器 + 预览 */}
      <main className="flex-1 flex overflow-hidden">
        {/* 移动端 Tab 切换 */}
        <div className="md:hidden flex border-b border-ink-800/60 shrink-0">
          <button
            onClick={() => setActiveTab('editor')}
            className={`flex-1 py-2 text-sm font-hei flex items-center justify-center gap-1.5 ${
              activeTab === 'editor' ? 'text-vermilion-400 border-b-2 border-vermilion-500' : 'text-ink-400'
            }`}
          >
            <Pen size={14} /> 编辑
          </button>
          <button
            onClick={() => setActiveTab('preview')}
            className={`flex-1 py-2 text-sm font-hei flex items-center justify-center gap-1.5 ${
              activeTab === 'preview' ? 'text-vermilion-400 border-b-2 border-vermilion-500' : 'text-ink-400'
            }`}
          >
            <BookOpen size={14} /> 预览
          </button>
        </div>

        {/* 左侧编辑区 */}
        <div className={`${activeTab !== 'editor' ? 'hidden md:flex' : 'flex'} flex-col w-full md:w-1/2 border-r border-ink-800/60`}>
          <div className="flex items-center px-4 py-2 bg-ink-900/60 border-b border-ink-800/40 shrink-0">
            <Pen size={12} className="text-ink-500 mr-2" />
            <span className="text-xs text-ink-400 font-hei">Markdown</span>
            <span className="ml-auto text-xs text-ink-600 font-hei">
              {markdown.length} 字符
            </span>
          </div>
          <textarea
            value={markdown}
            onChange={(e) => setMarkdown(e.target.value)}
            placeholder="在此粘贴或输入 Markdown 内容...&#10;&#10;支持标题、列表、表格、引用等格式&#10;点击右上角「示例」按钮可快速体验"
            className="flex-1 w-full p-5 bg-ink-950 text-ink-100 font-mono text-sm leading-relaxed resize-none focus:outline-none placeholder:text-ink-600 selection:bg-vermilion-500/30"
            spellCheck={false}
          />
        </div>

        {/* 右侧预览区 */}
        <div className={`${activeTab !== 'preview' ? 'hidden md:flex' : 'flex'} flex-col w-full md:w-1/2`}>
          <div className="flex items-center px-4 py-2 bg-ink-50 border-b border-ink-200 shrink-0">
            <BookOpen size={12} className="text-ink-400 mr-2" />
            <span className="text-xs text-ink-500 font-hei">排版预览</span>
            <span className="ml-auto flex items-center gap-1 text-xs text-ink-400 font-hei">
              <Sparkles size={10} className="text-gold-400" />
              {currentTemplate.name}
            </span>
          </div>
          <div className="flex-1 bg-ink-50 overflow-auto p-6">
            <div
              className="mx-auto shadow-lg"
              style={{
                maxWidth: '210mm',
                minHeight: '297mm',
                padding: `${currentTemplate.margins.top}mm ${currentTemplate.margins.right}mm ${currentTemplate.margins.bottom}mm ${currentTemplate.margins.left}mm`,
                background: '#faf8f5',
                backgroundImage: 'radial-gradient(circle at 20% 80%, rgba(200,180,150,0.05) 0%, transparent 50%), radial-gradient(circle at 80% 20%, rgba(200,180,150,0.03) 0%, transparent 50%)',
              }}
            >
              <Preview markdown={markdown} template={currentTemplate} />
            </div>
          </div>
        </div>
      </main>

      {/* 排版参数面板 */}
      <SettingsPanel template={currentTemplate} onUpdate={updateTemplate} />
    </div>
  );
}
